      { question: "Waarom klopte ‘weinig mensen’ niet volgens bewoners?", options: ["Het bad is al tien jaar dicht", "De banen liggen ’s ochtends vol met senioren", "Niemand kan zwemmen", "De krant verschijnt niet"], correct: 1, explanation: "’s Ochtends liggen de banen vol." },
      { question: "Wat beloofde de wethouder?", options: ["Een gratis jaarabonnement", "Een nieuw persbericht over katten", "Extra cijfers", "Sluiting van de redactie"], correct: 2, explanation: "De wethouder beloofde extra cijfers." },
      { question: "Waarom nam Jolien extra kranten mee?", options: ["Om ze te verkopen", "Om de Facebookgroep te sluiten", "Om foto’s te verwijderen", "Zodat ouderen zonder account het gesprek kunnen volgen"], correct: 3, explanation: "Gedrukte exemplaren zijn belangrijk voor ouderen zonder account." }
